use verus::prelude::*;

#[verifier(external_body)]   // we trust the body and only check the spec
#[requires(a.len() > 0)]
#[ensures(forall(|i: usize| i < a.len() ==> result >= a[i]))]
#[ensures(exists(|i: usize| i < a.len() && result == a[i]))]
fn max_array(a: &Vec<i32>) -> i32 {
    // Since the array is guaranteed non-empty, we can safely initialize
    // the maximum value to the first element.
    let mut max_val = a[0];

    // Iterate over the rest of the elements and update max_val as needed.
    for &num in a.iter().skip(1) {
        if num > max_val {
            max_val = num;
        }
    }

    max_val
}

